  let liftId = ex ? slewLiftFor(ex.leaf) : (S.settings.bpLift || 'Squat (free bar)');
  const lastW = ex ? (ex.sets.filter(s => s.w > 0).slice(-1)[0] || {}).w || 0 : 0;
