  if (isWarm(s)) s.done = true;                        // a measured warm-up is a done warm-up
  save(); bust(); render();
  const d = lvDay(ex);
  toast(d ? `e1RM today ${nice(dw(d.lo, 0))}–${nice(dw(d.hi, 0))} ${U()}` : `Point ${ex.lvp.points.length} · ${v.best.toFixed(2)} m/s at ${wt(s.w)}${v.place === 'pocket' ? ' (pocket — shown, not fitted)' : ''}`, d ? 'green' : '');
