const CAL_PCTS = [40, 55, 70, 80, 88];
export function openCalibrate(ei) {
  const ex = S.active && S.active.exercises[ei];
  if (!ex) return;
  const liftId = slewLiftFor(ex.leaf);
  if (!liftId) return toast('No velocity model for this movement yet');
  const key = exKey(ex);
  const est = autoE1(key) || (statsFor(key) ? statsFor(key).best.e1 : 0);
  ex.cal = ex.cal || { e1: est || 0, steps: [], fail: null };
  const c = ex.cal;
  const draw = () => {
    const loads = c.e1 ? CAL_PCTS.map(p => roundLoadFor(c.e1 * p / 100, ex.leaf)) : [];
    const pts = c.steps.filter(Boolean);
    const f = lvFit(pts);
    return `<div class="sub" style="margin-top:0">A measured ramp builds your own load-velocity profile for ${esc(exFull(ex))}. Phone on the bar, 2–3 fast reps per step, full rest. Skip anything that doesn't feel right.</div>
      <div class="field" style="margin-top:10px"><label for="calE1">Rough max today (${U()})</label>
        <input id="calE1" type="number" inputmode="decimal" step="2.5" value="${c.e1 ? nice(dw(c.e1)) : ''}" placeholder="e.g. 150"></div>
      ${loads.map((kg, i) => `<div class="row between" style="padding:6px 0;border-bottom:1px solid var(--line)">
        <span>${CAL_PCTS[i]}% · <b>${wt(kg)}</b></span>
        <span class="mono sub">${c.steps[i] ? `${c.steps[i].v.toFixed(2)} m/s${c.steps[i].place === 'pocket' ? ' · pocket' : ''}` : ''}</span>
        <button class="btn xs ${c.steps[i] ? 'ghost' : ''}" data-calstep="${i}">${c.steps[i] ? 'Redo' : 'Measure'}</button></div>`).join('')}
      ${loads.length ? `<div class="row between" style="padding:8px 0"><span>Optional: one set to failure at ~${wt(roundLoadFor(c.e1 * 0.75, ex.leaf))}<br><span class="sub">measures your limit speed and how fast you slow down</span></span>
        <button class="btn xs ${c.fail ? 'ghost' : ''}" data-calfail="1">${c.fail ? 'Redo' : 'Measure'}</button></div>` : ''}
      <div class="sub" style="margin-top:6px">${f ? `Line through ${f.n} points — ready to save.` : `${pts.length} of at least 3 steps measured.`}</div>`;
  };
  modal({
    title: `Calibrate · ${exName(ex)}`, body: draw(),
    foot: `<button class="btn ghost" data-close>Later</button><button class="btn primary" id="calSave">Save profile</button>`,
    onOpen: bg => {
      const reopen = () => { closeAllModals(); openCalibrate(ei); };
      const wire = () => {
        const inp = $('#calE1', bg);
        if (inp) inp.onchange = () => { c.e1 = +inp.value > 0 ? toKg(+inp.value) : 0; c.steps = []; save(); $('.modal-body', bg).innerHTML = draw(); wire(); };
        bg.querySelectorAll('[data-calstep]').forEach(b => b.onclick = () => {
          const i = +b.dataset.calstep, kg = roundLoadFor(c.e1 * CAL_PCTS[i] / 100, ex.leaf);
          closeAllModals();
          openVbtRecord(ei, { title: `Calibrate · step ${i + 1} of ${CAL_PCTS.length}`, note: `<b>${wt(kg)}</b> — 2–3 fast reps.`,
            onRecorded: v => { if (v.reps.length) c.steps[i] = { kg, v: v.best, place: v.place }; save(); reopen(); } });
        });
        bg.querySelectorAll('[data-calfail]').forEach(b => b.onclick = () => {
          const kg = roundLoadFor(c.e1 * 0.75, ex.leaf);
          closeAllModals();
          openVbtRecord(ei, { title: 'Calibrate · set to failure', note: `<b>${wt(kg)}</b> — reps until one won't go up. Safeties set.`,
            onRecorded: (v, est) => {
              c.fail = { kg, reps: v.reps.map(r => r.v), place: v.place, v0: est && est.measuredV0 ? est.measuredV0 : null };
              save(); reopen();
            } });
        });
      };
      wire();
      $('#calSave', bg).onclick = () => {
        const f = lvFit(c.steps.filter(Boolean));
        if (!f && !c.fail) return toast('Measure at least three steps first');
        if (f) {
          const mvt = mvtFor(liftId), e1 = (mvt - f.a) / f.b;
          S.settings.lvProfiles = S.settings.lvProfiles || {};
          S.settings.lvProfiles[key] = { a: f.a, b: f.b, n: 3, e1: e1 > 0 ? Math.round(e1 * 10) / 10 : null, at: Date.now(), lift: liftId, cal: true };
        }
        if (c.fail && c.fail.place !== 'pocket') {
          if (c.fail.v0) addMvtObservation(liftId, c.fail.v0);
          const fp = c.fail.reps.length >= 3 ? Slew.fitProfile(c.fail.reps, 10, slewProfile(liftId)) : null;
          if (fp && fp.vlF) saveSlewProfile(liftId, { vlF: fp.vlF, vlFCal: true, slope: fp.slope, cal: Date.now() });
        }
        delete ex.cal;
        save(); closeAllModals(); render();
        toast('Velocity profile saved for ' + exName(ex), 'green');
      };
    },
  });
}
